// === Tab: mySketch ===
// Inline shader code definitions:
const vert = `
  precision mediump float;
  attribute vec3 aPosition;
  void main() {
    gl_Position = vec4(aPosition, 1.0);
  }
`;

const TexFrag = `
  precision mediump float;
  uniform vec2 canvasSize;
  uniform vec2 texelSize;
  uniform vec2 mouse;
  uniform float time;
  uniform float scale;
  void main() {
    // Simple fragment that outputs a constant white color.
    gl_FragColor = vec4(1.0);
  }
`;

const BlurFrag = `
  precision mediump float;
  uniform vec2 canvasSize;
  uniform vec2 texelSize;
  uniform vec2 mouse;
  uniform float time;
  uniform float scale;
  uniform sampler2D tex0;
  uniform vec2 direction;
  void main() {
    vec2 uv = gl_FragCoord.xy / canvasSize;
    gl_FragColor = texture2D(tex0, uv);
  }
`;

const GrainFrag = `
  precision mediump float;
  uniform vec2 canvasSize;
  uniform vec2 texelSize;
  uniform vec2 mouse;
  uniform float time;
  uniform float scale;
  uniform sampler2D tex0;
  void main() {
    vec2 uv = gl_FragCoord.xy / canvasSize;
    gl_FragColor = texture2D(tex0, uv);
  }
`;

const MixFrag = `
  precision mediump float;
  uniform vec2 canvasSize;
  uniform vec2 texelSize;
  uniform vec2 mouse;
  uniform float time;
  uniform float scale;
  uniform sampler2D tex0;
  uniform sampler2D tex1;
  uniform vec3 color;
  void main() {
    vec2 uv = gl_FragCoord.xy / canvasSize;
    vec4 texColor = texture2D(tex0, uv);
    vec4 blendColor = texture2D(tex1, uv);
    gl_FragColor = mix(texColor, blendColor, 0.5) * vec4(color, 1.0);
  }
`;

new p5((p) => {
  // Canvas dimensions & texel size:
  const [WIDTH, HEIGHT] = [600, 600];
  const PIXEL_DENSITY = 1;
  const CANVAS_SIZE = [WIDTH, HEIGHT];
  const TEXEL_SIZE = [1 / (WIDTH * PIXEL_DENSITY), 1 / (HEIGHT * PIXEL_DENSITY)];

  // Shader passes:
  let TexPass, BlurPass, GrainPass, MixPass;
  let tex, gfx;
  let t, color;

  // Default palette
  const palette = ["#560100", "#060626", "#151f05"];
  const HCVertices = [];

  // Default parameters (which will be updated by sliders)
  let ORDER = 6;         // Hilbert curve order
  let NOISE_SCALE = 50;  // How strongly noise perturbs vertices
  let THICKNESS = 7;     // Stroke weight
  let SPEED = 0.5;       // Speed of noise evolution
  let SCALE = 2;         // Scale uniform for shaders
  let PADDING = 50;      // Padding from canvas edges
  let noiseMix = 0.5;    // Blend factor between noise sources

  // Sliders:
  let sliderDistortion, sliderOrder, sliderNoiseScale;
  let sliderStrokeWeight, sliderSpeed, sliderScale;
  let sliderPadding, sliderNoiseMix;

  p.setup = () => {
    p.createCanvas(WIDTH, HEIGHT);
    p.pixelDensity(PIXEL_DENSITY);

    // Create sliders below the canvas (position values are in pixels)
    let yPos = HEIGHT + 10;
    sliderDistortion = p.createSlider(0, WIDTH, WIDTH / 2, 1);
    sliderDistortion.position(10, yPos);
    p.createP("Distortion Control").position(sliderDistortion.x + sliderDistortion.width + 10, yPos - 15);

    yPos += 40;
    sliderOrder = p.createSlider(3, 7, ORDER, 1);
    sliderOrder.position(10, yPos);
    p.createP("Hilbert Order").position(sliderOrder.x + sliderOrder.width + 10, yPos - 15);

    yPos += 40;
    sliderNoiseScale = p.createSlider(0, 100, NOISE_SCALE, 1);
    sliderNoiseScale.position(10, yPos);
    p.createP("Noise Scale").position(sliderNoiseScale.x + sliderNoiseScale.width + 10, yPos - 15);

    yPos += 40;
    sliderStrokeWeight = p.createSlider(1, 20, THICKNESS, 1);
    sliderStrokeWeight.position(10, yPos);
    p.createP("Stroke Weight").position(sliderStrokeWeight.x + sliderStrokeWeight.width + 10, yPos - 15);

    yPos += 40;
    sliderSpeed = p.createSlider(0.1, 2, SPEED, 0.1);
    sliderSpeed.position(10, yPos);
    p.createP("Speed").position(sliderSpeed.x + sliderSpeed.width + 10, yPos - 15);

    yPos += 40;
    sliderScale = p.createSlider(1, 10, SCALE, 0.1);
    sliderScale.position(10, yPos);
    p.createP("Scale").position(sliderScale.x + sliderScale.width + 10, yPos - 15);

    yPos += 40;
    sliderPadding = p.createSlider(0, 100, PADDING, 1);
    sliderPadding.position(10, yPos);
    p.createP("Padding").position(sliderPadding.x + sliderPadding.width + 10, yPos - 15);

    yPos += 40;
    sliderNoiseMix = p.createSlider(0, 1, noiseMix, 0.01);
    sliderNoiseMix.position(10, yPos);
    p.createP("Noise Mix").position(sliderNoiseMix.x + sliderNoiseMix.width + 10, yPos - 15);

    // Create WEBGL graphics for shader passes:
    tex = p.createGraphics(WIDTH, HEIGHT, p.WEBGL);
    gfx = p.createGraphics(WIDTH, HEIGHT, p.WEBGL);

    TexPass = p.createShader(vert, TexFrag);
    BlurPass = p.createShader(vert, BlurFrag);
    GrainPass = p.createShader(vert, GrainFrag);
    MixPass = p.createShader(vert, MixFrag);

    initTex();
    setCurveStyles();
    updateHCVertices(); // compute the Hilbert curve vertices
    color = hex2rgb(p.random(palette));

    p.noLoop(); // Redraw only when a slider is changed.
  };

  p.draw = () => {
    // Update parameter values from sliders:
    ORDER = sliderOrder.value();
    NOISE_SCALE = sliderNoiseScale.value();
    THICKNESS = sliderStrokeWeight.value();
    SPEED = sliderSpeed.value();
    SCALE = sliderScale.value();
    PADDING = sliderPadding.value();
    noiseMix = sliderNoiseMix.value();

    // Recompute the Hilbert vertices since ORDER or PADDING may have changed:
    updateHCVertices();

    // Set stroke weight dynamically:
    p.strokeWeight(THICKNESS);

    // Compute time based on frameCount:
    t = (p.frameCount / 60) * SPEED;

    p.background(0);
    gfx.background(0);

    hilbertCurve();

    // Shader passes:
    if (!p._renderer) return;
    blur(p._renderer, [1, 0]);
    blur(gfx, [0, 1]);
    grain(gfx);
    mix(tex, gfx, color);
    p.image(gfx, 0, 0);
  };

  // Converts a hex string to an [r, g, b] array (each 0–1)
  const hex2rgb = (hex) => {
    const bigint = parseInt(hex.replace("#", ""), 16);
    return [
      ((bigint >> 16) & 255) / 255,
      ((bigint >> 8) & 255) / 255,
      (bigint & 255) / 255,
    ];
  };

  // Set up drawing styles for the Hilbert curve:
  const setCurveStyles = () => {
    p.stroke(255);
    p.noFill();
  };

  // Pass common uniforms to a shader:
  const commonUniform = (shader) => {
    shader.setUniform("canvasSize", CANVAS_SIZE);
    shader.setUniform("texelSize", TEXEL_SIZE);
    // Use the sliderDistortion for the horizontal value; vertical is fixed at 0.5.
    shader.setUniform("mouse", [sliderDistortion.value() / WIDTH, 0.5]);
    shader.setUniform("time", t);
    shader.setUniform("scale", SCALE);
  };

  // Initialize the texture pass:
  const initTex = () => {
    tex.shader(TexPass);
    commonUniform(TexPass);
    tex.quad(-1, 1, 1, 1, 1, -1, -1, -1);
  };

  // A simple blur shader pass:
  const blur = (texObj, direction) => {
    gfx.shader(BlurPass);
    commonUniform(BlurPass);
    BlurPass.setUniform("tex0", texObj);
    BlurPass.setUniform("direction", direction);
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1);
  };

  // A grain shader pass:
  const grain = (texObj) => {
    gfx.shader(GrainPass);
    commonUniform(GrainPass);
    GrainPass.setUniform("tex0", texObj);
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1);
  };

  // Mix two textures together:
  const mix = (base, blend, col) => {
    gfx.shader(MixPass);
    commonUniform(MixPass);
    MixPass.setUniform("tex0", base);
    MixPass.setUniform("tex1", blend);
    MixPass.setUniform("color", col);
    gfx.quad(-1, 1, 1, 1, 1, -1, -1, -1);
  };

  // Generate a noise offset for a given point using p5's noise
  const noisePosition = (pnt, t) => {
    const sPnt = p5.Vector.mult(pnt, 0.01);

    let nx = 0;
    nx += 1.0 * p.noise(1 * sPnt.x, 1 * sPnt.y, t);
    nx += 0.5 * p.noise(2 * sPnt.x, 2 * sPnt.y, t);
    nx += 0.25 * p.noise(4 * sPnt.x, 4 * sPnt.y, t);
    nx /= 1 + 0.5 + 0.25;

    let ny = 0;
    ny += 1.0 * p.noise(1 * sPnt.x, 1 * sPnt.y, t);
    ny += 0.5 * p.noise(2 * sPnt.x, 2 * sPnt.y, t);
    ny += 0.25 * p.noise(4 * sPnt.x, 4 * sPnt.y, t);
    ny /= 1 + 0.5 + 0.25;

    return [nx, ny];
  };

  // A smoothstep function for easing:
  const smoothstep = (edge0, edge1, x) => {
    x = p.constrain((x - edge0) / (edge1 - edge0), 0, 1);
    return x * x * (3 - 2 * x);
  };

  // Draw the Hilbert curve:
  const hilbertCurve = () => {
    // Use the distortion slider for the center:
    const mv = p.createVector(sliderDistortion.value(), HEIGHT / 2);
    p.beginShape();
    for (let i = -1; i <= HCVertices.length; i++) {
      const index = p.constrain(i, 0, HCVertices.length - 1);
      const pnt = HCVertices[index];
      hilbertCurveVertex(pnt, mv);
    }
    p.endShape();
  };

  // Distort each vertex with noise:
  const hilbertCurveVertex = (pnt, mv) => {
    const pntToCenter = pnt.dist(mv);
    const d = 1.5 * smoothstep(1.5, 0, pntToCenter / (WIDTH / SCALE));

    const [nx, ny] = noisePosition(pnt, t);
    // Additional perlin noise integration:
    const perlinX = p.noise(pnt.x * 0.01, pnt.y * 0.01, t);
    const perlinY = p.noise(pnt.y * 0.01, pnt.x * 0.01, t);
    const finalNx = p.lerp(nx, perlinX, noiseMix);
    const finalNy = p.lerp(ny, perlinY, noiseMix);

    const xoff = d * NOISE_SCALE * finalNx;
    const yoff = d * NOISE_SCALE * finalNy;

    if (false) {
      p.curveVertex(pnt.x + xoff, pnt.y + yoff);
    } else {
      p.vertex(pnt.x + xoff, pnt.y + yoff);
    }
  };

  // Compute and update the Hilbert curve vertices based on ORDER and PADDING.
  const updateHCVertices = () => {
    HCVertices.length = 0;
    getHCVertices(PADDING);
  };

  const getHCVertices = (padding) => {
    const GRID = p.pow(2, ORDER);
    const MAX_VERTICES = p.pow(GRID, 2);
    for (let i = 0; i < MAX_VERTICES; i++) {
      const pt = getHCVertex(i, GRID);
      const x = p.map(pt.x, 0, GRID - 1, padding, WIDTH - padding);
      const y = p.map(pt.y, 0, GRID - 1, padding, HEIGHT - padding);
      HCVertices.push(p.createVector(x, y));
    }
  };

  const getHCVertex = (i, GRID) => {
    const points = [
      p.createVector(0, 0),
      p.createVector(0, 1),
      p.createVector(1, 1),
      p.createVector(1, 0),
    ];

    var index = i & 3;
    const v = points[index].copy();

    for (let j = 1; j <= ORDER; j++) {
      index = (i >>= 2) & 3;
      const len = p.pow(2, j);

      if (index === 0) {
        [v.x, v.y] = [v.y, v.x];
      } else if (index === 1) {
        v.y += len;
      } else if (index === 2) {
        v.x += len;
        v.y += len;
      } else if (index === 3) {
        const tmp = len - 1 - v.x;
        v.x = len - 1 - v.y + len;
        v.y = tmp;
      }
    }

    // Adjust based on a fixed direction (p.TOP)
    if (p.TOP) {
      var tmp = v.x;
      v.x = v.y;
      v.y = GRID - 1 - tmp;
    }

    return v;
  };

  // Redraw when the mouse is released (after slider changes)
  p.mouseReleased = () => {
    p.redraw();
  };
});

